var a=`1112-ikan-sabuko`;var t=`world-1112`;var n=`TL`;var s=`southeast-asia`;var r=4;var o=73;var u={en:`Ikan Sabuko`,ua:`Ікан сабуко`};var d={en:`Ikan Sabuko is a dish from Timor-Leste prepared with skipjack tuna, tamarind concentrate, garlic, shallot. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ікан сабуко, страва кухні країни Тимор-Лешті, яку готують із таких продуктів: смугастий тунець, концентрат тамаринду, часник, цибуля шалот. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`skipjack-tuna`,730,`g`],[`tamarind-concentrate`,40,`g`],[`garlic`,4,`clove`],[`ground-turmeric`,5,`g`],[`table-salt`,6,`g`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[[`canola-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`shallot`,120,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`]]}];var l={slug:a,id:t,country:`TL`,region:s,servings:4,minutes:73,title:u,text:d,steps:g};export{n as country,l as default,t as id,o as minutes,s as region,r as servings,a as slug,g as steps,d as text,u as title};